import React, { useState, useEffect } from 'react';
import { View, StyleSheet, ActivityIndicator, Text, TouchableOpacity, Linking, Platform } from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import { getCurrentLocation, Hospital, LocationData } from '../services/locationService';

// Conditionally import MapView only on native platforms
let MapView: any = null;
let Marker: any = null;
let PROVIDER_GOOGLE: any = null;
let Region: any = null;

if (Platform.OS !== 'web') {
  try {
    const MapsModule = require('react-native-maps');
    MapView = MapsModule.default;
    Marker = MapsModule.Marker;
    PROVIDER_GOOGLE = MapsModule.PROVIDER_GOOGLE;
    Region = MapsModule.Region;
  } catch (e) {
    console.warn('react-native-maps not available');
  }
}

interface MapsViewProps {
  hospitals: Hospital[];
  onHospitalSelect?: (hospital: Hospital) => void;
  showUserLocation?: boolean;
  initialRegion?: Region;
}

export default function MapsView({
  hospitals,
  onHospitalSelect,
  showUserLocation = true,
  initialRegion,
}: MapsViewProps) {
  const [userLocation, setUserLocation] = useState<LocationData | null>(null);
  const [region, setRegion] = useState<Region>(
    initialRegion || {
      latitude: 37.78825,
      longitude: -122.4324,
      latitudeDelta: 0.0922,
      longitudeDelta: 0.0421,
    }
  );
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    loadUserLocation();
  }, []);

  const loadUserLocation = async () => {
    setLoading(true);
    const location = await getCurrentLocation();
    if (location) {
      setUserLocation(location);
      setRegion({
        ...region,
        latitude: location.latitude,
        longitude: location.longitude,
      });
    }
    setLoading(false);
  };

  const handleMarkerPress = (hospital: Hospital) => {
    if (onHospitalSelect) {
      onHospitalSelect(hospital);
    }
  };

  const openDirections = async (hospital: Hospital) => {
    const url = `https://www.google.com/maps/dir/?api=1&destination=${hospital.latitude},${hospital.longitude}`;
    try {
      const supported = await Linking.canOpenURL(url);
      if (supported) {
        await Linking.openURL(url);
      } else {
        console.log("Can't open maps URL");
      }
    } catch (error) {
      console.error('Error opening directions:', error);
    }
  };

  if (loading) {
    return (
      <View style={styles.loadingContainer}>
        <ActivityIndicator size="large" color="#007AFF" />
        <Text style={styles.loadingText}>Loading map...</Text>
      </View>
    );
  }

  return (
    <View style={styles.container}>
      <MapView
        provider={PROVIDER_GOOGLE}
        style={styles.map}
        region={region}
        onRegionChangeComplete={setRegion}
        showsUserLocation={showUserLocation && !!userLocation}
        showsMyLocationButton={true}
        showsCompass={true}
        toolbarEnabled={false}
      >
        {hospitals.map((hospital) => (
          <Marker
            key={hospital.id}
            coordinate={{
              latitude: hospital.latitude,
              longitude: hospital.longitude,
            }}
            title={hospital.name}
            description={hospital.address}
            onPress={() => handleMarkerPress(hospital)}
          >
            <View style={styles.markerContainer}>
              <View style={styles.markerGloss}>
                <Ionicons name="medical" size={24} color="#007AFF" />
              </View>
            </View>
          </Marker>
        ))}
      </MapView>
      
      {userLocation && (
        <TouchableOpacity
          style={styles.myLocationButton}
          onPress={loadUserLocation}
          activeOpacity={0.8}
        >
          <View style={styles.myLocationGloss}>
            <Ionicons name="locate" size={24} color="#007AFF" />
          </View>
        </TouchableOpacity>
      )}
    </View>
  );
}

const styles = StyleSheet.create({
  container: {
    flex: 1,
    borderRadius: 20,
    overflow: 'hidden',
  },
  map: {
    width: '100%',
    height: '100%',
  },
  loadingContainer: {
    flex: 1,
    justifyContent: 'center',
    alignItems: 'center',
    backgroundColor: '#F8F9FA',
  },
  loadingText: {
    marginTop: 10,
    color: '#666',
    fontSize: 16,
  },
  markerContainer: {
    alignItems: 'center',
    justifyContent: 'center',
  },
  markerGloss: {
    width: 50,
    height: 50,
    borderRadius: 25,
    backgroundColor: '#fff',
    justifyContent: 'center',
    alignItems: 'center',
    shadowColor: '#007AFF',
    shadowOffset: { width: 0, height: 4 },
    shadowOpacity: 0.3,
    shadowRadius: 8,
    elevation: 8,
    borderWidth: 3,
    borderColor: '#E3F2FD',
  },
  myLocationButton: {
    position: 'absolute',
    bottom: 20,
    right: 20,
  },
  myLocationGloss: {
    width: 50,
    height: 50,
    borderRadius: 25,
    backgroundColor: '#fff',
    justifyContent: 'center',
    alignItems: 'center',
    shadowColor: '#007AFF',
    shadowOffset: { width: 0, height: 4 },
    shadowOpacity: 0.3,
    shadowRadius: 8,
    elevation: 8,
    borderWidth: 2,
    borderColor: '#E3F2FD',
  },
});
